202	        // Set up timeline listener for real-time updates
203	        timelineListenerHandle = await timeline.addListener({
204	          onUpdate: (diffs) => {
205	            const beforeCount = timelineItemsRef.current.length;
206	            diffs.forEach((diff) => {
207	              const change = diff.tag;
208	              const timelineItems = timelineItemsRef.current;
209	              switch (change) {
210	                case TimelineDiff_Tags.Append: {
211	                  if (diff.inner.values.length > 0) {
212	                    timelineItems.push(...diff.inner.values.map(toEventItem));
213	                  }
214	                  break;
215	                }
216	                case TimelineDiff_Tags.Insert: {
217	                  const { index, value } = diff.inner;
218	                  timelineItems.splice(index, 0, toEventItem(value));
219	                  break;
220	                }
221	                case TimelineDiff_Tags.Set: {
222	                  const { index, value } = diff.inner;
223	                  const ev = toEventItem(value);
224	                  timelineItems[index] = ev;
225	
226	                  // transactionId -> eventId transition can arrive in an order where
227	                  // a stale local echo still exists elsewhere in the list.
228	                  if (
229	                    ev?.isOwn &&
230	                    !ev.localSendState &&
231	                    pendingTransactionIdsQueue.current.length > 0
232	                  ) {
233	                    const txId = pendingTransactionIdsQueue.current.shift();
234	                    if (txId) {
235	                      const txIndex = timelineItems.findIndex((item) => {
236	                        if (!item) return false;
237	                        return getItemUniqueKey(item) === txId;
238	                      });
239	                      if (txIndex !== -1) {
240	                        timelineItems[txIndex] = ev;
241	                      }
242	                    }
243	                  }
244	                  break;
245	                }
246	                case TimelineDiff_Tags.Remove: {
247	                  const { index: removeIndex } = diff.inner;
248	                  if (removeIndex >= 0 && removeIndex < timelineItems.length) {
249	                    timelineItems.splice(removeIndex, 1);
250	                  }
251	                  break;
252	                }
253	                case TimelineDiff_Tags.PushFront: {
254	                  const { value } = diff.inner;
255	                  timelineItems.unshift(toEventItem(value));
256	                  break;
257	                }
258	                case TimelineDiff_Tags.PushBack: {
259	                  const { value } = diff.inner;
260	                  const ev = toEventItem(value);
261	                  timelineItems.push(ev);
262	                  if (ev) {
263	                    const txId = getTransactionId(ev);
264	                    if (txId) {
265	                      pendingTransactionIdsQueue.current.push(txId);
266	                    }
267	                  }
268	                  break;
269	                }
270	                case TimelineDiff_Tags.PopFront: {
271	                  timelineItems.shift();
272	                  break;
273	                }
274	                case TimelineDiff_Tags.PopBack: {
275	                  timelineItems.pop();
276	                  break;
277	                }
278	                case TimelineDiff_Tags.Reset: {
279	                  const resetItems = diff.inner.values;
280	                  pendingTransactionIdsQueue.current = [];
281	                  timelineItemsRef.current = resetItems.map(toEventItem);
282	
283	                  const eventItems = timelineItemsRef.current.filter(
284	                    (i): i is EventTimelineItem => !!i,
285	                  );
286	                  pendingTransactionIdsQueue.current = eventItems
287	                    .map(getTransactionId)
288	                    .filter((id): id is string => !!id);
289	                  break;
290	                }
291	                case TimelineDiff_Tags.Truncate: {
292	                  const { length: cut } = diff.inner;
293	                  timelineItems.length = cut;
294	                  break;
295	                }
296	                case TimelineDiff_Tags.Clear: {
297	                  timelineItemsRef.current = [];
298	                  pendingTransactionIdsQueue.current = [];
299	                  eventIdsRef.current = new Set();
300	                  setEvents([]);
301	                  break;
302	                }
303	                default:
304	                  console.log("Unknown timeline change type:", change);
305	              }
