    markAsRead().catch(console.error);
    room?.isDirect().then(setIsDirect).catch(console.error);
  }, [room, markAsRead]);

  return {
    events,
    refreshing,
    timelineRef,
    isPaginatingRef,
    isDirect,
    loadMoreMessages,
    markAsRead,
  };
};

